CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, pw TEXT NOT NULL, name TEXT DEFAULT '', role TEXT DEFAULT 'user', plan TEXT DEFAULT 'free', memory_consent INTEGER DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE moods(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, v INTEGER NOT NULL, t INTEGER NOT NULL);
CREATE TABLE journal(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, t INTEGER NOT NULL);
CREATE TABLE favorites(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, content_id TEXT NOT NULL, PRIMARY KEY(user_id,content_id));
CREATE TABLE progress(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, content_id TEXT NOT NULL, count INTEGER DEFAULT 1, PRIMARY KEY(user_id,content_id));
CREATE TABLE chat(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, t INTEGER NOT NULL);
CREATE TABLE content(id INTEGER PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, category TEXT, url TEXT NOT NULL, thumb TEXT, lang TEXT DEFAULT 'en', duration INTEGER, description TEXT, license TEXT NOT NULL, tier TEXT DEFAULT 'free', published INTEGER DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY, actor INTEGER, action TEXT NOT NULL, detail TEXT, t INTEGER NOT NULL);
CREATE TABLE safety_events(id INTEGER PRIMARY KEY, user_id INTEGER, level TEXT NOT NULL, t INTEGER NOT NULL);
